21→
22→public:
23→	// --- Lifecycle ---
24→
25→	virtual void Initialize(FSubsystemCollectionBase& Collection) override;
26→	virtual void Deinitialize() override;
27→
28→	// --- Control ---
29→
30→	/** Start continuous viewport capture at the given FPS and resolution. */
31→	UFUNCTION(BlueprintCallable, Category = "ViewportPerception")
32→	void StartCapture(float MaxFPS = 5.0f, int32 Width = 1280, int32 Height = 720);
33→
34→	/** Stop continuous capture. */
35→	UFUNCTION(BlueprintCallable, Category = "ViewportPerception")
36→	void StopCapture();
37→
38→	/** Capture a single frame (starts capture, grabs one frame, stops). */
39→	UFUNCTION(BlueprintCallable, Category = "ViewportPerception")
40→	void RequestSingleFrame();
