42→	// --- Configuration ---
43→
44→	/** Set the output resolution for encoded images. */
45→	UFUNCTION(BlueprintCallable, Category = "ViewportPerception")
46→	void SetCaptureResolution(int32 Width, int32 Height);
47→
48→	/** Set maximum capture rate in frames per second. */
49→	UFUNCTION(BlueprintCallable, Category = "ViewportPerception")
50→	void SetMaxCaptureRate(float FPS);
51→
52→	/** Set the output image format (JPEG or PNG). */
53→	UFUNCTION(BlueprintCallable, Category = "ViewportPerception")
54→	void SetImageFormat(EPerceptionImageFormat Format);
55→
56→	/** Set JPEG quality (1-100). Only applies when format is JPEG. */
57→	UFUNCTION(BlueprintCallable, Category = "ViewportPerception")
58→	void SetJPEGQuality(int32 Quality);
59→
60→	// --- Reading ---
61→
62→	/** Get the latest encoded perception packet. Returns invalid packet if no frame available. */
63→	FPerceptionPacket GetLatestPacket();
64→
