69→	/** True if a new frame has arrived since the last GetLatestPacket call. */
70→	UFUNCTION(BlueprintCallable, Category = "ViewportPerception")
71→	bool HasNewFrame() const;
72→
73→	/** Get the HTTP endpoint instance (for route registration). */
