87→	EPerceptionImageFormat ImageFormat = EPerceptionImageFormat::JPEG;
88→	int32 JPEGQuality = 85;
89→
90→	// State
91→	int64 LastSeenFrame = 0;
92→	bool bSingleFrameRequested = false;
93→	bool bCapturing = false;
94→
95→	FDelegateHandle TickDelegateHandle;
96→};
