 12→void UViewportPerceptionSubsystem::Initialize(FSubsystemCollectionBase& Collection)
 13→{
 14→	Super::Initialize(Collection);
 15→
 16→	Producer = MakeUnique<FFrameProducer>();
 17→	Bus = MakeUnique<FPixelBus>();
 18→	Collector = MakeUnique<FMetadataCollector>();
 19→	Endpoint = MakeUnique<FPerceptionEndpoint>(this);
 20→
 21→	// Register tick for metadata collection (~20Hz)
 22→	TickDelegateHandle = FTSTicker::GetCoreTicker().AddTicker(
 23→		FTickerDelegate::CreateLambda([this](float DeltaTime) -> bool
 24→		{
 25→			this->OnTick(DeltaTime);
 26→			return true;
 27→		}),
 28→		0.05f
 29→	);
 30→
 31→	Endpoint->Start();
 32→
 33→	UE_LOG(LogViewportPerception, Log, TEXT("Subsystem initialized"));
 34→}
 35→
 36→void UViewportPerceptionSubsystem::Deinitialize()
 37→{
 38→	StopCapture();
 39→
 40→	if (Endpoint)
 41→	{
 42→		Endpoint->Stop();
 43→	}
 44→
 45→	FTSTicker::GetCoreTicker().RemoveTicker(TickDelegateHandle);
 46→
 47→	Endpoint.Reset();
 48→	Collector.Reset();
 49→	Bus.Reset();
 50→	Producer.Reset();
 51→
 52→	UE_LOG(LogViewportPerception, Log, TEXT("Subsystem deinitialized"));
 53→
 54→	Super::Deinitialize();
 55→}
