 57→void UViewportPerceptionSubsystem::StartCapture(float MaxFPS, int32 Width, int32 Height)
 58→{
 59→	CaptureResolution = FIntPoint(FMath::Max(Width, 64), FMath::Max(Height, 64));
 60→
 61→	if (Producer && Bus)
 62→	{
 63→		Producer->SetThrottleInterval(1.0 / FMath::Clamp(MaxFPS, 0.1f, 60.0f));
 64→		Producer->Start(Bus.Get());
 65→		bCapturing = true;
 66→		UE_LOG(LogViewportPerception, Log, TEXT("Capture started: %dx%d @ %.1f fps"),
 67→			CaptureResolution.X, CaptureResolution.Y, MaxFPS);
 68→	}
 69→}
