 71→void UViewportPerceptionSubsystem::StopCapture()
 72→{
 73→	if (Producer)
 74→	{
 75→		Producer->Stop();
 76→	}
 77→	bCapturing = false;
 78→	bSingleFrameRequested = false;
 79→}
