 21→void FFrameProducer::Start(FPixelBus* InPixelBus)
 22→{
 23→	if (bActive)
 24→	{
 25→		return;
 26→	}
 27→
 28→	check(InPixelBus);
 29→	PixelBus = InPixelBus;
 30→
 31→	if (FSlateApplication::IsInitialized())
 32→	{
 33→		DelegateHandle = FSlateApplication::Get().GetRenderer()->OnBackBufferReadyToPresent().AddRaw(
 34→			this, &FFrameProducer::OnFrameBufferReady);
 35→
 36→		bActive = true;
 37→		UE_LOG(LogViewportPerception, Log, TEXT("FrameProducer started (interval=%.2fs)"), MinCaptureInterval);
 38→	}
 39→	else
 40→	{
 41→		UE_LOG(LogViewportPerception, Warning, TEXT("Slate not initialized, cannot hook backbuffer"));
 42→	}
 43→}
