 45→void FFrameProducer::Stop()
 46→{
 47→	if (!bActive)
 48→	{
 49→		return;
 50→	}
 51→
 52→	if (FSlateApplication::IsInitialized() && DelegateHandle.IsValid())
 53→	{
 54→		FSlateApplication::Get().GetRenderer()->OnBackBufferReadyToPresent().Remove(DelegateHandle);
 55→		DelegateHandle.Reset();
 56→	}
 57→
 58→	bActive = false;
 59→	PixelBus = nullptr;
 60→	UE_LOG(LogViewportPerception, Log, TEXT("FrameProducer stopped"));
 61→}
