 63→void FFrameProducer::SetThrottleInterval(double Seconds)
 64→{
 65→	MinCaptureInterval = FMath::Max(Seconds, 0.01);  // Cap at 100fps
 66→}
 67→
 68→void FFrameProducer::OnFrameBufferReady(SWindow& SlateWindow, const FTexture2DRHIRef& FrameBuffer)
 69→{
 70→	// This runs on the render thread -- must be fast when skipping
 71→
 72→	// Throttle gate: skip if too soon since last capture
 73→	const double Now = FPlatformTime::Seconds();
 74→	if ((Now - LastCaptureTime) < MinCaptureInterval)
 75→	{
 76→		return;
 77→	}
 78→
 79→	if (!PixelBus || !FrameBuffer.IsValid())
 80→	{
 81→		return;
 82→	}
 83→
 84→	LastCaptureTime = Now;
 85→	const int64 CurrentFrame = FrameCounter.IncrementExchange() + 1;
 86→
 87→	// Read the backbuffer pixels
 88→	const FIntPoint Size = FrameBuffer->GetSizeXY();
 89→	TArray<FColor> Pixels;
 90→
 91→	FReadSurfaceDataFlags ReadFlags(RCM_UNorm);
 92→	ReadFlags.SetLinearToGamma(false);
 93→
 94→	// ReadSurfaceData on the current RHI command list
 95→	FRHICommandListImmediate& RHICmdList = FRHICommandListImmediate::Get();
 96→	RHICmdList.ReadSurfaceData(
 97→		FrameBuffer,
 98→		FIntRect(0, 0, Size.X, Size.Y),
 99→		Pixels,
100→		ReadFlags
101→	);
102→
103→	if (Pixels.Num() > 0)
104→	{
105→		PixelBus->WriteFrame(MoveTemp(Pixels), Size, CurrentFrame, Now);
106→	}
107→}
