 90→void FPerceptionEndpoint::Stop()
 91→{
 92→	if (!bRunning)
 93→	{
 94→		return;
 95→	}
 96→
 97→	FHttpServerModule& HttpModule = FHttpServerModule::Get();
 98→	TSharedPtr<IHttpRouter> Router = HttpModule.GetHttpRouter(PERCEPTION_PORT);
 99→
100→	if (Router.IsValid())
101→	{
102→		for (const FHttpRouteHandle& Handle : RouteHandles)
