114→bool FPerceptionEndpoint::HandleFrame(const FHttpServerRequest& Request,
115→                                       const FHttpResultCallback& OnComplete)
116→{
117→	if (!Subsystem)
118→	{
119→		SendJsonResponse(OnComplete, TEXT("{\"error\":\"Subsystem not available\"}"), 503);
120→		return true;
121→	}
122→
123→	FPerceptionPacket Packet = Subsystem->GetLatestPacket();
124→
125→	if (!Packet.bValid)
126→	{
127→		SendJsonResponse(OnComplete, TEXT("{\"error\":\"No frame available\"}"), 404);
128→		return true;
129→	}
130→
131→	// Build JSON response
132→	TSharedRef<FJsonObject> Root = MakeShared<FJsonObject>();
133→
134→	// Base64 encode the image
135→	FString ImageBase64 = FBase64::Encode(Packet.ImageData.GetData(), Packet.ImageData.Num());
136→	Root->SetStringField(TEXT("image"), ImageBase64);
137→	Root->SetNumberField(TEXT("width"), Packet.Width);
138→	Root->SetNumberField(TEXT("height"), Packet.Height);
139→	Root->SetStringField(TEXT("format"),
140→		Packet.Format == EPerceptionImageFormat::PNG ? TEXT("png") : TEXT("jpeg"));
141→	Root->SetNumberField(TEXT("frame_number"), static_cast<double>(Packet.FrameNumber));
142→	Root->SetNumberField(TEXT("timestamp"), Packet.Timestamp);
143→
144→	// Camera
145→	TSharedRef<FJsonObject> CameraObj = MakeShared<FJsonObject>();
146→	TArray<TSharedPtr<FJsonValue>> LocArr;
147→	LocArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Location.X));
148→	LocArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Location.Y));
149→	LocArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Location.Z));
150→	CameraObj->SetArrayField(TEXT("location"), LocArr);
151→
152→	TArray<TSharedPtr<FJsonValue>> RotArr;
153→	RotArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Rotation.Pitch));
154→	RotArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Rotation.Yaw));
155→	RotArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Rotation.Roll));
156→	CameraObj->SetArrayField(TEXT("rotation"), RotArr);
157→	CameraObj->SetNumberField(TEXT("fov"), Packet.Metadata.Camera.FOV);
158→	Root->SetObjectField(TEXT("camera"), CameraObj);
159→
160→	// Viewport
161→	TSharedRef<FJsonObject> ViewportObj = MakeShared<FJsonObject>();
162→	TArray<TSharedPtr<FJsonValue>> SizeArr;
163→	SizeArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.ViewportSize.X));
164→	SizeArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.ViewportSize.Y));
165→	ViewportObj->SetArrayField(TEXT("size"), SizeArr);
166→	ViewportObj->SetStringField(TEXT("type"), Packet.Metadata.ViewportType);
167→	Root->SetObjectField(TEXT("viewport"), ViewportObj);
168→
169→	// Selection
170→	TArray<TSharedPtr<FJsonValue>> SelArr;
171→	for (const FString& Name : Packet.Metadata.SelectedActors)
172→	{
173→		SelArr.Add(MakeShared<FJsonValueString>(Name));
174→	}
175→	Root->SetArrayField(TEXT("selection"), SelArr);
176→
177→	// Scene
178→	TSharedRef<FJsonObject> SceneObj = MakeShared<FJsonObject>();
179→	SceneObj->SetStringField(TEXT("map"), Packet.Metadata.MapName);
180→	SceneObj->SetNumberField(TEXT("actor_count"), Packet.Metadata.ActorCount);
181→	Root->SetObjectField(TEXT("scene"), SceneObj);
182→
183→	// Timing
184→	TSharedRef<FJsonObject> TimingObj = MakeShared<FJsonObject>();
185→	TimingObj->SetNumberField(TEXT("delta_time"), Packet.Metadata.DeltaTime);
186→	TimingObj->SetNumberField(TEXT("fps"), Packet.Metadata.FPS);
187→	Root->SetObjectField(TEXT("timing"), TimingObj);
188→
189→	// Serialize
190→	FString JsonBody;
191→	TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&JsonBody);
192→	FJsonSerializer::Serialize(Root, Writer);
193→
194→	SendJsonResponse(OnComplete, JsonBody);
195→	return true;
196→}
