216→bool FPerceptionEndpoint::HandleConfig(const FHttpServerRequest& Request,
217→                                        const FHttpResultCallback& OnComplete)
218→{
219→	if (!Subsystem)
220→	{
221→		SendJsonResponse(OnComplete, TEXT("{\"error\":\"Subsystem not available\"}"), 503);
222→		return true;
223→	}
224→
225→	// Parse request body as JSON
226→	FString BodyStr = UTF8_TO_TCHAR(reinterpret_cast<const char*>(Request.Body.GetData()));
227→
228→	TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(BodyStr);
229→	TSharedPtr<FJsonObject> Body;
230→
231→	if (FJsonSerializer::Deserialize(Reader, Body) && Body.IsValid())
232→	{
233→		double MaxFPS;
234→		if (Body->TryGetNumberField(TEXT("max_fps"), MaxFPS))
235→		{
236→			Subsystem->SetMaxCaptureRate(static_cast<float>(MaxFPS));
237→		}
238→
239→		int32 Width = 0, Height = 0;
240→		if (Body->TryGetNumberField(TEXT("width"), Width) &&
241→		    Body->TryGetNumberField(TEXT("height"), Height))
242→		{
243→			Subsystem->SetCaptureResolution(Width, Height);
244→		}
245→
246→		FString Format;
247→		if (Body->TryGetStringField(TEXT("format"), Format))
248→		{
249→			Subsystem->SetImageFormat(
250→				Format.Equals(TEXT("png"), ESearchCase::IgnoreCase)
251→					? EPerceptionImageFormat::PNG
252→					: EPerceptionImageFormat::JPEG
253→			);
254→		}
255→
256→		int32 Quality;
257→		if (Body->TryGetNumberField(TEXT("quality"), Quality))
258→		{
259→			Subsystem->SetJPEGQuality(Quality);
260→		}
261→	}
262→
263→	SendJsonResponse(OnComplete, TEXT("{\"status\":\"configured\"}"));
264→	return true;
265→}
