267→bool FPerceptionEndpoint::HandleStart(const FHttpServerRequest& Request,
268→                                       const FHttpResultCallback& OnComplete)
269→{
270→	if (!Subsystem)
271→	{
272→		SendJsonResponse(OnComplete, TEXT("{\"error\":\"Subsystem not available\"}"), 503);
273→		return true;
274→	}
275→
276→	// Parse optional params from body
277→	float FPS = 5.0f;
278→	int32 Width = 1280, Height = 720;
279→
280→	FString BodyStr = UTF8_TO_TCHAR(reinterpret_cast<const char*>(Request.Body.GetData()));
281→	TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(BodyStr);
282→	TSharedPtr<FJsonObject> Body;
283→
284→	if (FJsonSerializer::Deserialize(Reader, Body) && Body.IsValid())
285→	{
286→		double V;
287→		if (Body->TryGetNumberField(TEXT("fps"), V)) FPS = static_cast<float>(V);
288→		Body->TryGetNumberField(TEXT("width"), Width);
289→		Body->TryGetNumberField(TEXT("height"), Height);
290→	}
291→
292→	Subsystem->StartCapture(FPS, Width, Height);
293→	SendJsonResponse(OnComplete, TEXT("{\"status\":\"capturing\"}"));
294→	return true;
295→}
296→
297→bool FPerceptionEndpoint::HandleStop(const FHttpServerRequest& Request,
298→                                      const FHttpResultCallback& OnComplete)
299→{
300→	if (Subsystem)
301→	{
302→		Subsystem->StopCapture();
303→	}
304→
305→	SendJsonResponse(OnComplete, TEXT("{\"status\":\"stopped\"}"));
306→	return true;
307→}
308→
309→bool FPerceptionEndpoint::HandleSingle(const FHttpServerRequest& Request,
310→                                        const FHttpResultCallback& OnComplete)
311→{
312→	if (!Subsystem)
313→	{
314→		SendJsonResponse(OnComplete, TEXT("{\"error\":\"Subsystem not available\"}"), 503);
315→		return true;
316→	}
317→
318→	// If not capturing, start a temporary capture
319→	const bool WasCapturing = Subsystem->IsCapturing();
320→	if (!WasCapturing)
321→	{
322→		Subsystem->RequestSingleFrame();
323→	}
324→
325→	// Give the frame a moment to arrive, then try to read
326→	// We schedule a delayed response via async
327→	AsyncTask(ENamedThreads::GameThread, [this, OnComplete, WasCapturing]()
328→	{
329→		// Try to get a frame with a brief spin (up to 500ms)
330→		FPerceptionPacket Packet;
331→		constexpr float MaxWait = 0.5f;
332→		constexpr float PollInterval = 0.05f;
333→		float Waited = 0.0f;
334→
335→		while (Waited < MaxWait)
336→		{
337→			Packet = Subsystem->GetLatestPacket();
338→			if (Packet.bValid)
339→			{
340→				break;
341→			}
342→			FPlatformProcess::Sleep(PollInterval);
343→			Waited += PollInterval;
344→		}
345→
346→		// Stop if we started it
347→		if (!WasCapturing)
348→		{
349→			Subsystem->StopCapture();
350→		}
351→
352→		if (!Packet.bValid)
353→		{
354→			SendJsonResponse(OnComplete, TEXT("{\"error\":\"Capture timed out\"}"), 408);
355→			return;
356→		}
357→
358→		// Build the same JSON response as HandleFrame
359→		TSharedRef<FJsonObject> Root = MakeShared<FJsonObject>();
360→		FString ImageBase64 = FBase64::Encode(Packet.ImageData.GetData(), Packet.ImageData.Num());
361→		Root->SetStringField(TEXT("image"), ImageBase64);
362→		Root->SetNumberField(TEXT("width"), Packet.Width);
363→		Root->SetNumberField(TEXT("height"), Packet.Height);
364→		Root->SetStringField(TEXT("format"),
365→			Packet.Format == EPerceptionImageFormat::PNG ? TEXT("png") : TEXT("jpeg"));
366→		Root->SetNumberField(TEXT("frame_number"), static_cast<double>(Packet.FrameNumber));
367→		Root->SetNumberField(TEXT("timestamp"), Packet.Timestamp);
368→
369→		TSharedRef<FJsonObject> CameraObj = MakeShared<FJsonObject>();
370→		TArray<TSharedPtr<FJsonValue>> LocArr;
371→		LocArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Location.X));
372→		LocArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Location.Y));
373→		LocArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Location.Z));
374→		CameraObj->SetArrayField(TEXT("location"), LocArr);
375→		TArray<TSharedPtr<FJsonValue>> RotArr;
376→		RotArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Rotation.Pitch));
377→		RotArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Rotation.Yaw));
378→		RotArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Rotation.Roll));
379→		CameraObj->SetArrayField(TEXT("rotation"), RotArr);
380→		CameraObj->SetNumberField(TEXT("fov"), Packet.Metadata.Camera.FOV);
381→		Root->SetObjectField(TEXT("camera"), CameraObj);
382→
383→		TSharedRef<FJsonObject> SceneObj = MakeShared<FJsonObject>();
384→		SceneObj->SetStringField(TEXT("map"), Packet.Metadata.MapName);
385→		SceneObj->SetNumberField(TEXT("actor_count"), Packet.Metadata.ActorCount);
386→		Root->SetObjectField(TEXT("scene"), SceneObj);
387→
388→		TArray<TSharedPtr<FJsonValue>> SelArr;
389→		for (const FString& Name : Packet.Metadata.SelectedActors)
390→		{
391→			SelArr.Add(MakeShared<FJsonValueString>(Name));
392→		}
393→		Root->SetArrayField(TEXT("selection"), SelArr);
394→
395→		FString JsonBody;
396→		TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&JsonBody);
397→		FJsonSerializer::Serialize(Root, Writer);
398→
399→		SendJsonResponse(OnComplete, JsonBody);
400→	});
401→
402→	return true;  // We'll respond asynchronously
403→}
404→
405→void FPerceptionEndpoint::SendJsonResponse(const FHttpResultCallback& OnComplete,
406→                                            const FString& JsonBody, int32 StatusCode)
407→{
408→	auto Response = FHttpServerResponse::Create(JsonBody, TEXT("application/json"));
409→	OnComplete(MoveTemp(Response));
410→}
