14→FPerceptionMetadata FMetadataCollector::Collect()
15→{
16→	check(IsInGameThread());
17→
18→	FPerceptionMetadata Meta;
19→
20→	// Get the active level editor viewport
21→	if (GEditor)
22→	{
23→		// Try to get the active viewport client
24→		FEditorViewportClient* ViewportClient = nullptr;
25→
26→		FLevelEditorModule& LevelEditorModule = FModuleManager::GetModuleChecked<FLevelEditorModule>("LevelEditor");
27→		TSharedPtr<ILevelEditor> LevelEditor = LevelEditorModule.GetFirstLevelEditor();
28→		if (LevelEditor.IsValid())
29→		{
30→			TSharedPtr<SLevelViewport> ActiveViewport = LevelEditor->GetActiveViewportInterface();
31→			if (ActiveViewport.IsValid())
32→			{
33→				ViewportClient = &ActiveViewport->GetLevelViewportClient();
34→			}
35→		}
36→
37→		if (ViewportClient)
38→		{
39→			// Camera
40→			Meta.Camera.Location = ViewportClient->GetViewLocation();
41→			Meta.Camera.Rotation = ViewportClient->GetViewRotation();
42→			Meta.Camera.FOV = ViewportClient->ViewFOV;
43→
44→			// Viewport size
45→			FIntPoint ViewSize = ViewportClient->Viewport ? ViewportClient->Viewport->GetSizeXY() : FIntPoint::ZeroValue;
46→			Meta.ViewportSize = ViewSize;
47→
48→			// Viewport type
49→			if (ViewportClient->IsSimulateInEditorViewport())
50→			{
51→				Meta.ViewportType = TEXT("SIE");
52→			}
53→			else if (GEditor->PlayWorld != nullptr)
54→			{
55→				Meta.ViewportType = TEXT("PIE");
56→			}
57→			else
58→			{
59→				Meta.ViewportType = TEXT("LevelEditor");
60→			}
61→		}
62→
63→		// Selected actors
64→		USelection* Selection = GEditor->GetSelectedActors();
65→		if (Selection)
66→		{
67→			for (int32 i = 0; i < Selection->Num(); ++i)
68→			{
69→				AActor* Actor = Cast<AActor>(Selection->GetSelectedObject(i));
70→				if (Actor)
71→				{
72→					Meta.SelectedActors.Add(Actor->GetActorLabel());
73→				}
74→			}
75→		}
76→
77→		// Map name and actor count
78→		UWorld* World = GEditor->GetEditorWorldContext().World();
79→		if (World)
80→		{
81→			Meta.MapName = World->GetMapName();
82→
83→			int32 Count = 0;
84→			for (TActorIterator<AActor> It(World); It; ++It)
85→			{
86→				++Count;
87→			}
88→			Meta.ActorCount = Count;
89→		}
90→
91→		// Timing
92→		Meta.DeltaTime = FApp::GetDeltaTime();
93→		Meta.FPS = (Meta.DeltaTime > 0.0f) ? (1.0f / Meta.DeltaTime) : 0.0f;
94→	}
95→
96→	return Meta;
97→}
